import json
import os
from pathlib import Path

from . import model


def _read_uint(value, name):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError('field %r must be an integer' % name)
    if value < 0:
        raise ValueError('field %r must be non-negative' % name)
    return value


def _read_str(value, name):
    if not isinstance(value, str):
        raise ValueError('field %r must be a string' % name)
    if not value.strip():
        raise ValueError('field %r must not be empty' % name)
    return value


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {'name', 'result'}:
        return payload['result']
    return payload


def _max_weight(items, cooldown):
    items = sorted(items, key=lambda x: (x['end'], x['start'], x['id']))
    n = len(items)
    if n == 0:
        return 0
    dp = [0] * n
    for i in range(n):
        best = 0
        for j in range(i):
            if items[j]['end'] + cooldown <= items[i]['start']:
                if dp[j] > best:
                    best = dp[j]
        dp[i] = best + items[i]['value']
    return max(0, max(dp))


def _solve(windows, cooldown):
    W = _max_weight(windows, cooldown)
    items = sorted(windows, key=lambda w: w['id'])

    def compatible(a, b):
        return a['end'] + cooldown <= b['start'] or b['end'] + cooldown <= a['start']

    chosen = []

    def value(chs):
        return sum(c['value'] for c in chs)

    for x in items:
        if value(chosen) == W:
            break
        if all(compatible(x, c) for c in chosen):
            cand = chosen + [x]
            allowed = [w for w in items
                       if w not in cand and all(compatible(w, c) for c in cand)]
            base = value(cand)
            extra = _max_weight(allowed, cooldown)
            if base + extra == W:
                chosen = cand

    selected = sorted(c['id'] for c in chosen)
    return {'selected': selected, 'value': value(chosen)}


def transform(payloads, contract):
    if not isinstance(payloads, (list, tuple)):
        raise ValueError('payloads must be a list')
    expected_inputs = contract.get('inputs', [])
    if len(payloads) != len(expected_inputs):
        raise ValueError('expected %d payloads' % len(expected_inputs))

    cooldown = contract.get('cooldown', 0)
    if isinstance(cooldown, bool) or not isinstance(cooldown, int) or cooldown < 0:
        raise ValueError('invalid cooldown')

    raw = _unwrap(payloads[0])
    if not isinstance(raw, dict):
        raise ValueError('windows payload must be an object')
    windows_raw = raw.get('windows')
    if not isinstance(windows_raw, list):
        raise ValueError('windows must be a list')

    windows = []
    seen = set()
    for entry in windows_raw:
        if not isinstance(entry, dict):
            raise ValueError('window entry must be an object')
        wid = _read_str(entry.get('id'), 'id').strip()
        if wid in seen:
            raise ValueError('duplicate window id %r' % wid)
        seen.add(wid)
        start = _read_uint(entry.get('start'), 'start')
        end = _read_uint(entry.get('end'), 'end')
        if end <= start:
            raise ValueError('window end must be greater than start')
        value = entry.get('value')
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError('window value must be an integer')
        windows.append({'id': wid, 'start': start, 'end': end, 'value': value})

    result = _solve(windows, cooldown)
    return {'name': contract['name'], 'result': result}
